const m=[{term:"summary before detail",means:"Put what the person must check or decide first; the supporting detail follows.",plain:["show the important bit first","put that at the top"]},{term:"visual hierarchy",means:"The order the eye takes through a screen, set by size, weight, colour and position.",plain:["make it more obvious","it gets lost"]},{term:"proximity",means:"Things placed close together read as belonging together; space between them says they do not.",plain:["group these","it feels scattered"]},{term:"contrast",means:"How far apart two things are in lightness, size or colour — what makes one stand out from another.",plain:["make it pop","it's hard to see"]},{term:"primary action",means:"The one thing a screen most wants the person to do next, drawn so it is found first.",plain:["the main button","what should I press"]},{term:"type scale",means:"A small fixed set of text sizes, each a step from the last, used everywhere instead of one-off sizes.",plain:["the fonts are all different sizes","tidy the text sizes"]},{term:"progressive disclosure",means:"Show what is needed now and reveal the rest when it is asked for.",plain:["too much at once","hide the advanced stuff"]},{term:"gate before value",means:"Asking for something (a sign-up, a permission) before the person has seen what they get for it.",plain:["make them sign up first"]},{term:"scan line",means:"The path the eye runs down a list; breaking its alignment makes a list slow to read.",plain:["hard to skim","the list is messy"]},{term:"density",means:"How much sits in a given space — tight for experts scanning, loose for people reading.",plain:["it feels cramped","too empty"]},{term:"affordance",means:"What a thing looks like it lets you do: a button that looks pressable, a field that looks typeable.",plain:["I didn't know I could click it"]},{term:"fidelity",means:"How finished a drawing looks — a rough wireframe invites change; a polished screen invites approval.",plain:["just a sketch","make it look real"]}];function p(a){const n=[...m].sort((e,s)=>s.term.length-e.term.length),r=e=>e.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"),h=new RegExp(`\\b(${n.map(e=>r(e.term)).join("|")})\\b`,"gi"),o=[];let t=0;for(const e of a.matchAll(h)){const s=e.index??0;s>t&&o.push({text:a.slice(t,s)});const i=n.find(l=>l.term===e[0].toLowerCase());o.push(i?{text:e[0],word:i}:{text:e[0]}),t=s+e[0].length}return t<a.length&&o.push({text:a.slice(t)}),o}export{p as d};
